SELECT u.id, u.nickname, u.avatar
FROM user_follows AS f
INNER JOIN users AS u ON u.id = f.followee_id
WHERE f.follower_id = #{userId}
ORDER BY f.created_at, f.followee_id
LIMIT #{offset}, #{limit}

